// Portable Popcount: Brian Kernighan's Algorithm
int popcount_bk(unsigned int n) {
    int count = 0;
    while (n != 0) {
        n &= (n - 1); // Clears the least significant set bit
        count++;
    }
    return count;
}

// High Performance: Compiler Intrinsics (GCC/Clang/MSVC)
unsigned int flags = 0x80000001;
int count_32bit = __builtin_popcount(flags);

unsigned long long large_flags = 0xFFFFFFULL;
int count_64bit = __builtin_popcountll(large_flags);

